#include <iostream>

class MyType {
    int val;
public:
    MyType(int v) : val(v) {}
    bool operator==(const MyType& other) const { return val == other.val; }

    // REQUIRED: Must manually define operator!= (pre-C++20)
    bool operator!=(const MyType& other) const { return !(*this == other); }
};

int main() {
    MyType a(5);
    MyType b(10);

    // This call requires the manually defined operator!=
    if (a != b) {
        std::cout << "Objects are not equal.\n";
    }
}
